// Core tests: the 12 literal core cases from the fixed spec's
// fixtures.json (vendored verbatim at test/fixtures.json from spec
// candidate b68311b57e79ddbbae922a0672b4bd8fe299ba3a; expected values
// taken verbatim, never generated by the product), plus the CNY
// table's SPEC-pinned self-consistency, the ganzhi formula anchors,
// and independently derived endpoint, Ben Ming Nian, grammar, and
// validation-order cases. The derived success expectations were
// produced by an independent scratch implementation of the SPEC's
// stated rules, which itself reproduces all 12 literal fixtures.

import assert from "node:assert/strict";
import test from "node:test";
import {
  ANIMALS,
  CNY_DATES,
  gregorianToDayNumber,
  run,
  STEMS,
} from "../public/js/core/zodiac.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

function dayNumberOf(text) {
  const [y, m, d] = text.split("-").map(Number);
  return gregorianToDayNumber(y, m, d);
}

test("CNY table self-consistency: 78 rows, Jan 21-Feb 20, legal year gaps", () => {
  const years = Object.keys(CNY_DATES).map(Number).sort((a, b) => a - b);
  assert.deepEqual(years, Array.from({ length: 78 }, (_, i) => 1959 + i));
  let previous = null;
  for (const year of years) {
    const text = CNY_DATES[year];
    const [, month, day] = text.split("-").map(Number);
    assert.ok(
      (month === 1 && day >= 21) || (month === 2 && day <= 20),
      `${year}: ${text} outside Jan 21 - Feb 20`,
    );
    const dayNumber = dayNumberOf(text);
    if (previous !== null) {
      assert.ok(
        [353, 354, 355, 383, 384, 385].includes(dayNumber - previous),
        `${year}: illegal gap ${dayNumber - previous}`,
      );
    }
    previous = dayNumber;
  }
});

test("ganzhi formula anchors from the SPEC", () => {
  const anchors = [
    [1960, "庚子", "鼠"],
    [1984, "甲子", "鼠"],
    [2000, "庚辰", "龍"],
    [2024, "甲辰", "龍"],
    [2035, "乙卯", "兔"],
    [2036, "丙辰", "龍"],
  ];
  for (const [year, ganzhi, animalZh] of anchors) {
    const animal = ANIMALS[(((year - 4) % 12) + 12) % 12];
    const stem = STEMS[(((year - 4) % 10) + 10) % 10];
    assert.equal(`${stem.zh}${animal.branch}`, ganzhi, `${year} ganzhi`);
    assert.equal(animal.zh, animalZh, `${year} animal`);
  }
});

// Independently derived: 2024 is a leap year, and 2024-02-29 falls
// after CNY 2024-02-10, so it is a Jia-Chen Dragon date.
test("derived: 2024-02-29 is a real leap day in the Dragon year", () => {
  assert.deepEqual(run({ birthDate: "2024-02-29", asOfDate: "" }), {
    ok: true,
    result: {
      zodiacYear: 2024,
      animalIndex: 4,
      animalZh: "龍",
      animalEn: "Dragon",
      branchZh: "辰",
      stemZh: "甲",
      elementZh: "木",
      elementEn: "Wood",
      ganzhiZh: "甲辰",
      spanStart: "2024-02-10",
      spanEnd: "2025-01-28",
      cnyOfBirthYear: "2024-02-10",
      beforeCny: false,
      asOfZodiacYear: null,
      isBenMingNian: null,
      nextBenMingNianYear: null,
      nextBenMingNianStart: null,
    },
  });
});

