// Independently derived: the highest legal as-of date, 2036-12-31, is
// in the 2036 Bing-Chen Dragon year; a 2024 Dragon birth makes it a
// Ben Ming Nian whose next one (2048) is beyond the table.
test("derived: as-of high endpoint 2036-12-31 in a Ben Ming Nian", () => {
  assert.deepEqual(run({ birthDate: "2024-03-01", asOfDate: "2036-12-31" }), {
    ok: true,
    result: {
      zodiacYear: 2024,
      animalIndex: 4,
      animalZh: "龍",
      animalEn: "Dragon",
      branchZh: "辰",
      stemZh: "甲",
      elementZh: "木",
      elementEn: "Wood",
      ganzhiZh: "甲辰",
      spanStart: "2024-02-10",
      spanEnd: "2025-01-28",
      cnyOfBirthYear: "2024-02-10",
      beforeCny: false,
      asOfZodiacYear: 2036,
      isBenMingNian: true,
      nextBenMingNianYear: 2048,
      nextBenMingNianStart: null,
    },
  });
});

// Independently derived: from a 2035 as-of (Rabbit year), the next
// Dragon year is 2036, whose CNY is still inside the table.
test("derived: next Ben Ming Nian start inside the table", () => {
  const outcome = run({ birthDate: "2024-03-01", asOfDate: "2035-06-01" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.asOfZodiacYear, 2035);
  assert.equal(outcome.result.isBenMingNian, false);
  assert.equal(outcome.result.nextBenMingNianYear, 2036);
  assert.equal(outcome.result.nextBenMingNianStart, "2036-01-28");
});

// Independently derived: a Snake birth read at 2036 (Dragon year) has
// its next Ben Ming Nian in 2037, beyond the table, so only the year
// is known.
test("derived: next Ben Ming Nian year beyond the table has a null start", () => {
  const outcome = run({ birthDate: "2025-03-01", asOfDate: "2036-06-01" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.zodiacYear, 2025);
  assert.equal(outcome.result.ganzhiZh, "乙巳");
  assert.equal(outcome.result.asOfZodiacYear, 2036);
  assert.equal(outcome.result.isBenMingNian, false);
  assert.equal(outcome.result.nextBenMingNianYear, 2037);
  assert.equal(outcome.result.nextBenMingNianStart, null);
});

// Independently derived: the as-of date may precede the birth date;
// the SPEC pins no cross-field order check.
test("derived: as-of date before the birth date is accepted", () => {
  const outcome = run({ birthDate: "2025-01-29", asOfDate: "1960-06-15" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.asOfZodiacYear, 1960);
  assert.equal(outcome.result.isBenMingNian, false);
  assert.equal(outcome.result.nextBenMingNianYear, 1965);
  assert.equal(outcome.result.nextBenMingNianStart, "1965-02-02");
});

test("empty birth date is EMPTY; empty as-of date means not provided", () => {
  assert.deepEqual(run({ birthDate: "", asOfDate: "" }), {
    ok: false,
    error: { code: "EMPTY", field: "birthDate", row: null },
  });
  assert.equal(run({ birthDate: "2025-01-29", asOfDate: "" }).ok, true);
});

test("grammar and real-date codes on both fields", () => {
  assert.deepEqual(run({ birthDate: "2025-01-15", asOfDate: "2025.06.01" }), {
    ok: false,
    error: { code: "DATE_FORMAT", field: "asOfDate", row: null },
  });
  assert.deepEqual(run({ birthDate: "2025-13-01", asOfDate: "" }), {
    ok: false,
    error: { code: "DATE_INVALID", field: "birthDate", row: null },
  });
  assert.deepEqual(run({ birthDate: "2025-04-31", asOfDate: "" }), {
    ok: false,
    error: { code: "DATE_INVALID", field: "birthDate", row: null },
  });
  assert.deepEqual(run({ birthDate: "2025-01-00", asOfDate: "" }), {
    ok: false,
    error: { code: "DATE_INVALID", field: "birthDate", row: null },
  });
});

test("as-of range endpoints just outside are OUT_OF_RANGE on asOfDate", () => {
  assert.deepEqual(run({ birthDate: "2025-01-29", asOfDate: "1959-12-31" }), {
    ok: false,
    error: { code: "OUT_OF_RANGE", field: "asOfDate", row: null },
  });
  assert.deepEqual(run({ birthDate: "2025-01-29", asOfDate: "2037-01-01" }), {
    ok: false,
    error: { code: "OUT_OF_RANGE", field: "asOfDate", row: null },
  });
});

test("capacity fires before Unicode and grammar: INPUT_LIMIT", () => {
  assert.deepEqual(run({ birthDate: "2025-01-15".padEnd(33, " "), asOfDate: "" }), {
    ok: false,
    error: { code: "INPUT_LIMIT", field: "birthDate", row: null },
  });
  assert.deepEqual(run({ birthDate: "2025-01-15", asOfDate: "x".repeat(33) }), {
    ok: false,
    error: { code: "INPUT_LIMIT", field: "asOfDate", row: null },
  });
});

test("unpaired surrogate is UNICODE, before grammar", () => {
  assert.deepEqual(run({ birthDate: "2025-01-1\uD800", asOfDate: "" }), {
    ok: false,
    error: { code: "UNICODE", field: "birthDate", row: null },
  });
  assert.deepEqual(run({ birthDate: "2025-01-15", asOfDate: "\uDC00" }), {
    ok: false,
    error: { code: "UNICODE", field: "asOfDate", row: null },
  });
});

test("field order: a birthDate error beats any asOfDate error", () => {
  assert.deepEqual(run({ birthDate: "", asOfDate: "not-a-date" }), {
    ok: false,
    error: { code: "EMPTY", field: "birthDate", row: null },
  });
  assert.deepEqual(run({ birthDate: "2025-02-29", asOfDate: "2037-01-01" }), {
    ok: false,
    error: { code: "DATE_INVALID", field: "birthDate", row: null },
  });
});

test("schema rejects non-plain shapes", () => {
  const shape = { ok: false, error: { code: "SCHEMA", field: null, row: null } };
  assert.deepEqual(run(null), shape);
  assert.deepEqual(run(["2025-01-15", ""]), shape);
  assert.deepEqual(run("2025-01-15"), shape);
  assert.deepEqual(run({ birthDate: "2025-01-15" }), shape);
  assert.deepEqual(run({ birthDate: "2025-01-15", asOfDate: "", extra: "x" }), shape);
  assert.deepEqual(run({ birthDate: 20250115, asOfDate: "" }), {
    ok: false,
    error: { code: "SCHEMA", field: "birthDate", row: null },
  });
});

test("schema rejects accessors without invoking them", () => {
  let invoked = false;
  const input = { birthDate: "2025-01-15" };
  Object.defineProperty(input, "asOfDate", {
    enumerable: true,
    get() {
      invoked = true;
      return "";
    },
  });
  assert.deepEqual(run(input), {
    ok: false,
    error: { code: "SCHEMA", field: "asOfDate", row: null },
  });
  assert.equal(invoked, false);
});

test("invariant sweep: every sampled birth date lands inside its zodiac span", () => {
  for (let year = 1960; year <= 2035; year += 1) {
    for (const [month, day] of [[1, 1], [1, 27], [2, 10], [2, 20], [6, 15], [12, 31]]) {
      const date = `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
      const outcome = run({ birthDate: date, asOfDate: "" });
      assert.equal(outcome.ok, true, date);
      const { result } = outcome;
      assert.equal(result.spanStart, CNY_DATES[result.zodiacYear], date);
      assert.equal(
        dayNumberOf(result.spanEnd) + 1,
        dayNumberOf(CNY_DATES[result.zodiacYear + 1]),
        date,
      );
      const birthDay = dayNumberOf(date);
      assert.ok(
        dayNumberOf(result.spanStart) <= birthDay && birthDay <= dayNumberOf(result.spanEnd),
        date,
      );
      assert.equal(result.beforeCny, birthDay < dayNumberOf(result.cnyOfBirthYear), date);
      assert.equal(result.animalIndex, (((result.zodiacYear - 4) % 12) + 12) % 12, date);
    }
  }
});
